  document.querySelectorAll('li.node').forEach(li=>setCollapsed(li,false));
});
document.getElementById('collapseAll').addEventListener('click', ()=>{
  // 所有「自身还带子列表」的节点都收起，但保留每个分支的一级子节点（R1..R8 等）可见
  document.querySelectorAll('li.node').forEach(li=>{
