    if(!own) return;
    const inBranch = !!li.closest('.branch');
    const isBranchChild = !!li.parentElement && li.parentElement.classList.contains('tree')
                         && li.parentElement.parentElement.classList.contains('branch');
    setCollapsed(li, inBranch && !isBranchChild);
  });
});

