  const t = li.querySelector(':scope > .toggle');
  if(t){ t.classList.toggle('collapsed', collapsed); t.setAttribute('aria-expanded', String(!collapsed)); }
}
/** 一级节点（R1..R8 等）：收起时只隐藏它的子列表，标题本身保留可见 */
function setHideKids(li, hidden){
  li.classList.toggle('hidekids', hidden);
  const t = li.querySelector(':scope > .toggle');
  if(t) t.setAttribute('aria-expanded', String(!hidden));
}
document.getElementById('expandAll').addEventListener('click', ()=>{
  document.querySelectorAll('li.node').forEach(li=>{
    setCollapsed(li,false);
    setHideKids(li,false);
  });
});
document.getElementById('collapseAll').addEventListener('click', ()=>{
  // 一级节点（父级是分支的 ul.tree）：收起其子列表但保留标题
  // 更深层节点：整条收起
  document.querySelectorAll('li.node').forEach(li=>{
    const own = li.querySelector(':scope > ul');
    if(!own) return;
    const isFirstLevel = !!li.parentElement
      && li.parentElement.classList.contains('tree')
      && li.parentElement.parentElement.classList.contains('branch');
    if(isFirstLevel){ setHideKids(li,true); setCollapsed(li,false); }
    else { setCollapsed(li,true); setHideKids(li,false); }
  });
});

