func (s *Server) handleDailyReport(w http.ResponseWriter, r *http.Request, _ service.Identity) {
	tenantID, err := s.tenantScope(r, service.Identity{SubjectType: domain.SubjectAdmin, Role: domain.AdminOps, TenantID: r.URL.Query().Get("tenant_id")})
	if err != nil {
