package httpapi

import (
	"fmt"
	"net/http"

	"modelquota/internal/domain"
	"modelquota/internal/service"
)

// ---------- 租户管理员接口（R1/R6/R7） ----------

func (s *Server) handleListCredentials(w http.ResponseWriter, r *http.Request, identity service.Identity) {
	tenantID, err := s.tenantScope(r, identity)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	creds, err := s.svc.DB().ListCredentialsByTenant(r.Context(), tenantID)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"credentials": creds})
}

type createCredentialRequest struct {
	Name string `json:"name"`
	// TenantID 故意不作为参数使用：凭证所属租户由系统确认（R1）。
	// 保留字段仅为让越权尝试能被显式拒绝，而不是静默忽略。
	TenantID string `json:"tenant_id"`
}

func (s *Server) handleCreateCredential(w http.ResponseWriter, r *http.Request, identity service.Identity) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, fmt.Errorf("仅支持 POST"))
		return
	}
	var in createCredentialRequest
	if err := decodeJSON(r, &in); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	// 越权尝试：请求体指定了其他租户 —— 直接拒绝（R1）。
	if in.TenantID != "" && in.TenantID != identity.TenantID {
		writeError(w, statusFor(domain.ErrTenantMismatch), domain.ErrTenantMismatch)
		return
	}
	cred, secret, err := s.svc.CreateCredential(r.Context(), identity.Username, identity.TenantID,
		service.CredentialInput{Name: in.Name})
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"credential": cred, "secret": secret})
}

type disableCredentialRequest struct {
	CredentialID string `json:"credential_id"`
	Reason       string `json:"reason"`
}

func (s *Server) handleDisableCredential(w http.ResponseWriter, r *http.Request, identity service.Identity) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, fmt.Errorf("仅支持 POST"))
		return
	}
	var in disableCredentialRequest
	if err := decodeJSON(r, &in); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if err := s.svc.DisableCredential(r.Context(), identity.Username, identity.TenantID, in.CredentialID, in.Reason); err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"status": "disabled", "credential_id": in.CredentialID})
}

func (s *Server) handleTenantUsage(w http.ResponseWriter, r *http.Request, identity service.Identity) {
	tenantID, err := s.tenantScope(r, identity)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	day := dayParam(r, s.svc.Clock())
	usage, err := s.svc.TenantUsage(r.Context(), tenantID, day)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"usage": map[string]any{
			"tenant_id":   usage.TenantID,
			"day":         usage.Day,
			"quota_limit": usage.QuotaLimit,
			"success":     usage.Success,
			"in_flight":   usage.InFlight,
			"occupied":    usage.Occupied(),
			"remaining":   usage.Remaining(),
		},
	})
}

func (s *Server) handleTenantRequests(w http.ResponseWriter, r *http.Request, identity service.Identity) {
	tenantID, err := s.tenantScope(r, identity)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	day := dayParam(r, s.svc.Clock())
	reqs, err := s.svc.RequestsByTenant(r.Context(), tenantID, day)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	rejected, err := s.svc.RejectedAttempts(r.Context(), tenantID, day)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"requests": reqs, "rejected": rejected})
}

// ---------- 客户应用接口（R3/R4/R7） ----------

type invokeRequest struct {
	RequestNo string         `json:"request_no"`
	Model     string         `json:"model"`
	Prompt    string         `json:"prompt"`
	Params    map[string]any `json:"params"`
}

func (s *Server) handleInvoke(w http.ResponseWriter, r *http.Request, identity service.Identity) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, fmt.Errorf("仅支持 POST"))
		return
	}
	var in invokeRequest
	if err := decodeJSON(r, &in); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	result, err := s.svc.Invoke(r.Context(), "credential:"+identity.SubjectID, identity.TenantID, identity.SubjectID,
		service.InvokeInput{
			RequestNo: in.RequestNo,
			Model:     in.Model,
			Prompt:    in.Prompt,
			Params:    in.Params,
		})
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"request":     result.Request,
		"replayed":    result.Replayed,
		"usage":       result.Usage,
		"diagnostics": result.Diagnostics,
	})
}

func (s *Server) handleCredentialRequests(w http.ResponseWriter, r *http.Request, identity service.Identity) {
	day := dayParam(r, s.svc.Clock())
	reqs, err := s.svc.RequestsByCredential(r.Context(), identity.SubjectID, day)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"requests": reqs})
}

func (s *Server) handleGetRequest(w http.ResponseWriter, r *http.Request, identity service.Identity) {
	requestNo := r.URL.Query().Get("request_no")
	if requestNo == "" {
		writeError(w, http.StatusBadRequest, domain.ErrRequestNoRequired)
		return
	}
	req, err := s.svc.DB().GetRequestByNo(r.Context(), identity.TenantID, requestNo)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	// 应用仅可查询由其凭证创建的请求（R7）。
	if req.CredentialID != identity.SubjectID {
		writeError(w, statusFor(domain.ErrForbidden), domain.ErrForbidden)
		return
	}
	diags, err := s.svc.DB().ListDiagnosticsByRequest(r.Context(), req.ID)
	if err != nil {
		writeError(w, statusFor(err), err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"request": req, "diagnostics": diags})
}

package httpapi

import (
	"embed"
	"fmt"
	"html/template"
	"net/http"
	"strings"

	"modelquota/internal/domain"
	"modelquota/internal/service"
)

//go:embed web/templates/*.html
var templateFS embed.FS

// templates 持有页面模板集合。
type templates struct {
	layout   *template.Template
	login    *template.Template
	ops      *template.Template
	admin    *template.Template
	app      *template.Template
	notFound *template.Template
}

// LoadTemplates 加载页面模板。
func LoadTemplates() (*templates, error) {
	parse := func(name string) (*template.Template, error) {
		return template.New(name).Funcs(template.FuncMap{
			"statusLabel": func(s domain.RequestStatus) string {
				switch s {
				case domain.RequestSuccess:
					return "成功"
				case domain.RequestFailed:
					return "失败"
				case domain.RequestTimeout:
					return "超时"
				case domain.RequestProcessing:
					return "处理中"
				case domain.RequestRejected:
					return "被拒绝"
				default:
					return string(s)
				}
			},
			"tenantStatusLabel": func(s domain.TenantStatus) string {
				switch s {
				case domain.TenantActive:
					return "已开通"
				case domain.TenantPending:
					return "待开通"
				case domain.TenantDisabled:
					return "已停用"
				default:
					return string(s)
				}
			},
			"credentialStatusLabel": func(s domain.CredentialStatus) string {
				switch s {
				case domain.CredentialActive:
					return "可用"
				case domain.CredentialDisabled:
					return "已停用"
				default:
					return string(s)
				}
			},
		}).ParseFS(templateFS, "web/templates/"+name)
	}

	layout, err := parse("layout.html")
	if err != nil {
		return nil, fmt.Errorf("加载布局模板失败: %w", err)
	}
	login, err := parse("login.html")
	if err != nil {
		return nil, fmt.Errorf("加载登录模板失败: %w", err)
	}
	ops, err := parse("ops.html")
	if err != nil {
		return nil, fmt.Errorf("加载运营模板失败: %w", err)
	}
	admin, err := parse("admin.html")
	if err != nil {
		return nil, fmt.Errorf("加载管理员模板失败: %w", err)
	}
	app, err := parse("app.html")
	if err != nil {
		return nil, fmt.Errorf("加载应用模板失败: %w", err)
	}
	notFound, err := parse("notfound.html")
	if err != nil {
		return nil, fmt.Errorf("加载未找到模板失败: %w", err)
	}
	return &templates{layout: layout, login: login, ops: ops, admin: admin, app: app, notFound: notFound}, nil
}

// pageData 是页面统一数据。
type pageData struct {
	Title    string
	Identity service.Identity
	Today    string
	Now      string
	Error    string
	Message  string
	Data     any
}

// render 渲染页面（先执行布局模板再执行内容模板）。
func (s *Server) render(w http.ResponseWriter, status int, tmpl *template.Template, data pageData) {
	var buf strings.Builder
	if err := tmpl.Execute(&buf, data); err != nil {
		http.Error(w, "页面渲染失败: "+err.Error(), http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.WriteHeader(status)
	_, _ = w.Write([]byte(buf.String()))
}

// requireIdentity 解析身份，失败时跳转到登录页。
func (s *Server) requireIdentity(w http.ResponseWriter, r *http.Request) (service.Identity, bool) {
	identity, err := s.identityFrom(r)
	if err != nil {
		http.Redirect(w, r, "/login", http.StatusSeeOther)
		return service.Identity{}, false
	}
	return identity, true
}

func (s *Server) baseData(r *http.Request, identity service.Identity, title string) pageData {
	return pageData{
		Title:    title,
		Identity: identity,
		Today:    s.svc.CurrentDay(),
		Now:      s.svc.Clock().Now().Format("2006-01-02 15:04:05 UTC"),
		Error:    r.URL.Query().Get("error"),
		Message:  r.URL.Query().Get("message"),
	}
}

// handleIndex 按身份跳转到对应工作台。
func (s *Server) handleIndex(w http.ResponseWriter, r *http.Request) {
	identity, err := s.identityFrom(r)
	if err != nil {
		http.Redirect(w, r, "/login", http.StatusSeeOther)
		return
	}
	switch {
	case identity.IsOps():
		http.Redirect(w, r, "/ops", http.StatusSeeOther)
	case identity.IsTenantAdmin():
		http.Redirect(w, r, "/admin", http.StatusSeeOther)
	default:
		http.Redirect(w, r, "/app", http.StatusSeeOther)
	}
}

// handleLoginPage 渲染登录页。
func (s *Server) handleLoginPage(w http.ResponseWriter, r *http.Request) {
	data := pageData{Title: "登录", Now: s.svc.Clock().Now().Format("2006-01-02 15:04:05 UTC")}
	s.render(w, http.StatusOK, s.templates.login, data)
}

// opsView 是运营工作台的数据。
type opsView struct {
	Tenants     []domain.Tenant
	Reports     []opsReportRow
	Diagnostics []domain.Diagnostic
	Day         string
}

// opsReportRow 是某租户当日的核查行。
type opsReportRow struct {
	TenantID string
	Report   *domain.DailyReport
}

func (s *Server) handleOpsPage(w http.ResponseWriter, r *http.Request) {
	identity, ok := s.requireIdentity(w, r)
	if !ok {
		return
	}
	if !identity.IsOps() {
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	day := dayParam(r, s.svc.Clock())

	tenants, err := s.svc.DB().ListTenants(r.Context())
	if err != nil {
		s.renderOpsError(w, r, identity, err)
		return
	}
	view := opsView{Tenants: tenants, Day: day}
	for _, t := range tenants {
		report, err := s.svc.DailyReport(r.Context(), t.ID, day)
		if err != nil {
			continue
		}
		view.Reports = append(view.Reports, opsReportRow{TenantID: t.ID, Report: report})
	}
	diags, err := s.svc.Diagnostics(r.Context(), "")
	_ = diags
	_ = err

	data := s.baseData(r, identity, "平台运营工作台")
	data.Data = view
	s.render(w, http.StatusOK, s.templates.ops, data)
}

func (s *Server) renderOpsError(w http.ResponseWriter, r *http.Request, identity service.Identity, err error) {
	data := s.baseData(r, identity, "平台运营工作台")
	data.Error = err.Error()
	s.render(w, http.StatusInternalServerError, s.templates.ops, data)
}

// adminView 是租户管理员工作台的数据。
type adminView struct {
	TenantID    string
	Tenant      *domain.Tenant
	Credentials []domain.Credential
	Usage       domain.Usage
	Requests    []domain.ModelRequest
	Rejected    []domain.RejectedAttempt
	Day         string
}

func (s *Server) handleAdminPage(w http.ResponseWriter, r *http.Request) {
	identity, ok := s.requireIdentity(w, r)
	if !ok {
		return
	}
	if !identity.IsTenantAdmin() {
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	day := dayParam(r, s.svc.Clock())

	tenant, err := s.svc.DB().GetTenant(r.Context(), identity.TenantID)
	if err != nil {
		s.renderAdminError(w, r, identity, err)
		return
	}
	creds, err := s.svc.DB().ListCredentialsByTenant(r.Context(), identity.TenantID)
	if err != nil {
		s.renderAdminError(w, r, identity, err)
		return
	}
	usage, err := s.svc.TenantUsage(r.Context(), identity.TenantID, day)
	if err != nil {
		s.renderAdminError(w, r, identity, err)
		return
	}
	reqs, err := s.svc.RequestsByTenant(r.Context(), identity.TenantID, day)
	if err != nil {
		s.renderAdminError(w, r, identity, err)
		return
	}
	rejected, err := s.svc.RejectedAttempts(r.Context(), identity.TenantID, day)
	if err != nil {
		s.renderAdminError(w, r, identity, err)
		return
	}

	data := s.baseData(r, identity, "客户管理员工作台")
	data.Data = adminView{
		TenantID:    identity.TenantID,
		Tenant:      tenant,
		Credentials: creds,
		Usage:       usage,
		Requests:    reqs,
		Rejected:    rejected,
		Day:         day,
	}
	s.render(w, http.StatusOK, s.templates.admin, data)
}

func (s *Server) renderAdminError(w http.ResponseWriter, r *http.Request, identity service.Identity, err error) {
	data := s.baseData(r, identity, "客户管理员工作台")
	data.Error = err.Error()
	s.render(w, http.StatusInternalServerError, s.templates.admin, data)
}

// appView 是客户应用工作台的数据。
type appView struct {
	CredentialID string
	Day          string
	Requests     []domain.ModelRequest
}

func (s *Server) handleAppPage(w http.ResponseWriter, r *http.Request) {
	identity, ok := s.requireIdentity(w, r)
	if !ok {
		return
	}
	if !identity.IsCredential() {
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	day := dayParam(r, s.svc.Clock())
	reqs, err := s.svc.RequestsByCredential(r.Context(), identity.SubjectID, day)
	if err != nil {
		data := s.baseData(r, identity, "客户应用工作台")
		data.Error = err.Error()
		s.render(w, http.StatusInternalServerError, s.templates.app, data)
		return
	}

	data := s.baseData(r, identity, "客户应用工作台")
	data.Data = appView{CredentialID: identity.SubjectID, Day: day, Requests: reqs}
	s.render(w, http.StatusOK, s.templates.app, data)
}

