  * { box-sizing:border-box; }
  body { margin:0; font:14px/1.6 "Segoe UI","Microsoft YaHei",sans-serif; color:var(--fg); background:#f5f7fb; }
  header { background:#fff; border-bottom:1px solid var(--bd); padding:12px 24px; display:flex; align-items:center; gap:16px; }
  header h1 { font-size:16px; margin:0; }
