  table { border-collapse:collapse; width:100%; font-size:13px; }
  th,td { border:1px solid var(--bd); padding:6px 8px; text-align:left; vertical-align:top; }
  th { background:#f0f3f9; font-weight:600; }
  input,select,textarea { padding:5px 7px; border:1px solid var(--bd); border-radius:4px; font:inherit; }
  button { padding:6px 14px; border:1px solid var(--acc); background:var(--acc); color:#fff; border-radius:4px; cursor:pointer; font:inherit; }
