// TestInvokeRequestNoNotReusableAcrossDays 验证请求编号跨日不复用。
//
// 题面要求编号「全局唯一」：跨天后同一编号改用不同参数必须拒绝，
// 参数相同则仍视为同一次调用的重放。
func TestInvokeRequestNoNotReusableAcrossDays(t *testing.T) {
	svc, _, _ := newTestService(t)
