	if _, err := svc.Invoke(ctx, "app", testTenantA, "cred-a1",
		InvokeInput{RequestNo: "req-1", Model: "m", Prompt: "p"}); err != nil {
		t.Fatalf("首次调用失败: %v", err)
	}

	// 把时钟推到第二天。
	svc.SetClockOffset(24 * time.Hour)
	if svc.CurrentDay() == testDay {
		t.Fatalf("教学时钟推进后当前日期应变化")
