	_, err := svc.Invoke(ctx, "app", testTenantA, "cred-a1",
		InvokeInput{RequestNo: "req-1", Model: "m", Prompt: "新的提示词"})
	if !errors.Is(err, domain.ErrRequestNoConflict) {
		t.Fatalf("跨日复用编号应被拒绝，实际 %v", err)
	}
}

