	svc, up, _ := newTestService(t)
	ctx := context.Background()

	if _, err := svc.Invoke(ctx, "app", testTenantA, "cred-a1",
		InvokeInput{RequestNo: "req-1", Model: "m", Prompt: "p"}); err != nil {
