	}
	changes, err := db.ListQuotaChanges(ctx, tenant.ID, testDay)
	if err != nil {
		t.Fatalf("列出配额变更失败: %v", err)
	}
	if len(changes) != 1 || changes[0].Reason == "" {
		t.Fatalf("应写入默认原因: %+v", changes)
	}

