// TestAppCannotReadOtherCredentialRequest 验证应用不能查询其他凭证的请求（R7）。
func TestAppCannotReadOtherCredentialRequest(t *testing.T) {
	srv, _ := newTestServer(t)
	h := srv.Handler()
	opsToken := login(t, h, "ops", "ops-****")

	// 运营在 tenantB 下创建一个凭证并用它发起请求。
	rec := do(t, h, http.MethodPost, "/api/v1/admin/credentials/create", opsToken,
		map[string]any{"name": "app-b1"})
	var created struct {
		Credential domain.Credential `json:"credential"`
		Secret     string            `json:"secret"`
	}
	decodeJSONBody(t, rec, &created)
	if rec.Code != http.StatusOK {
		t.Fatalf("创建凭证状态码 = %d: %s", rec.Code, rec.Body.String())
	}
	// 运营身份没有租户归属，无法代建租户凭证时改用直接登录既有凭证。
	_ = created

	// tenantA 的应用凭证查询 tenantB 的请求编号应被拒绝。
	rec = do(t, h, http.MethodPost, "/api/v1/auth/login", "", map[string]string{"secret": "sk-a1"})
	var loginOut struct {
		Token string `json:"token"`
	}
	decodeJSONBody(t, rec, &loginOut)
	do(t, h, http.MethodPost, "/api/v1/app/invoke", loginOut.Token,
		map[string]any{"request_no": "req-b", "model": "m", "prompt": "p"})

	// 该请求属于 tenantA 的凭证，另一个凭证查询时必然被拒。
