// AddTestHook 注册一个测试钩子。
func (s *Service) AddTestHook(hook TestHook) { s.TestHooks = append(s.TestHooks, hook) }

// handleLateResult 处理上游在 2 秒硬时限之后才返回的「迟到结果」（R4）。
//
// 口径要求：
//   - 只写 diagnostics 表，作为诊断记录保留；
//   - 不修改已经返回的超时终态；
//   - 不追加扣额、不计入成功量。
//
// 该回调由上游客户端在后台协程中触发，因此必须使用独立上下文，
// 不能依赖原调用方的请求上下文（那可能已经结束）。
func (s *Service) handleLateResult(correlationID string, resp *upstream.Response, callErr error) {
	if correlationID == "" {
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	req, err := s.db.GetRequest(ctx, correlationID)
	if err != nil {
		return
	}
	// 只有已经按超时结案的请求才可能有迟到结果。
	if req.Status != domain.RequestTimeout {
		return
	}

	detail := ""
	switch {
	case callErr == nil && resp != nil:
		detail = fmt.Sprintf("迟到结果（上游在超时后返回成功）：upstream_id=%s，耗时=%s",
			resp.UpstreamID, resp.Latency.Round(time.Millisecond))
	case callErr != nil:
		detail = "迟到失败结果（上游在超时后返回失败）：" + callErr.Error()
	default:
		return
	}
	// 忽略写入失败：诊断记录不得影响主流程结论。
	_ = s.db.InsertDiagnostic(ctx, &domain.Diagnostic{
		ID:         newID("diag"),
		RequestID:  req.ID,
		TenantID:   req.TenantID,
		Kind:       "late_result",
		Detail:     detail,
		RecordedAt: s.clk.Now(),
	})
}

	// 上游调用上下文与调用方的取消信号解绑，但保留取值：
	//  1. 调用方（HTTP 请求）结束后不会误伤仍在等待的上游调用；
	//  2. 判定超时后不取消它，从而能观测到迟到结果（R4）；
	//  3. 仍保留 LateWait 上限，避免后台协程无限期挂起。
	lateWait := c.LateWait
	if lateWait <= 0 {
		lateWait = DefaultLateWait
	}
	upstreamCtx, cancelUpstream := context.WithTimeout(context.WithoutCancel(ctx), lateWait)

	// 调用方主动取消（如 HTTP 客户端断开）仍应中断上游调用；
	// 但一旦判定超时，就停止观察调用方取消信号，保留迟到结果的观测窗口。
	stopWatch := make(chan struct{})
	go func() {
		select {
		case <-ctx.Done():
			cancelUpstream()
		case <-stopWatch:
		}
	}()

	httpReq, err := http.NewRequestWithContext(upstreamCtx, http.MethodPost,
		c.BaseURL+"/v1/complete", bytes.NewReader(body))
	if err != nil {
		close(stopWatch)
		cancelUpstream()
		return nil, fmt.Errorf("构造上游请求失败: %w", err)
	}
	httpReq.Header.Set("Content-Type", "application/json")

	started := time.Now()
	// 缓冲通道：即使调用方已经返回，后台协程也不会阻塞。
	ch := make(chan callResult, 1)
	go func() {
		ch <- c.do(upstreamCtx, httpReq, started)
	}()

	timer := time.NewTimer(timeout)
	defer timer.Stop()

	select {
	case r := <-ch:
		close(stopWatch)
		cancelUpstream()
		return r.resp, r.err
	case <-timer.C:
		// 判定超时（R4）：返回 ErrTimeout，上层释放额度占用、不计成功量。
		// 后台继续等待上游，若随后返回则上报迟到结果。
		if ctx.Err() != nil {
			// 调用方已取消：没有迟到结果可言，直接结束。
			close(stopWatch)
			cancelUpstream()
			return nil, ErrTimeout
		}
		close(stopWatch)
		go c.awaitLateResult(req.CorrelationID, ch, cancelUpstream)
		return nil, ErrTimeout
	}
}

