func (f *fakeUpstream) fireLateResult(correlationID string, resp *upstream.Response, callErr error) {
	f.mu.Lock()
	handler := f.handler
	f.mu.Unlock()
	if handler != nil {
		handler(correlationID, resp, callErr)
	}
}

