	if res.Request.Status != domain.RequestTimeout {
		t.Fatalf("终态 = %s，期望 timeout", res.Request.Status)
	}
	if len(res.Diagnostics) != 0 {
		t.Fatalf("尚未收到迟到结果时不应有诊断记录，实际 %d 条", len(res.Diagnostics))
	}

	// 上游在超时之后返回成功。
