		RequestSuccess, RequestFailed, RequestTimeout, RequestProcessing, RequestRejected,
	} {
		n, ok := report.Counts[status]
		if !ok {
			t.Fatalf("日报缺少终态 %s", status)
		}
		if status != RequestSuccess && n != 0 {
			t.Fatalf("终态 %s 的计数 = %d, 期望 0", status, n)
		}
