// TestAPIErrorsMaskInternalDetails 验证接口层 500 不透出数据库内部细节。
func TestAPIErrorsMaskInternalDetails(t *testing.T) {
	srv, _ := newTestServer(t)
	h := srv.Handler()
	token := login(t, h, "ops", "ops-****")
	if err := srv.svc.DB().Close(); err != nil {
		t.Fatalf("关闭数据库失败: %v", err)
	}
	rec := do(t, h, http.MethodGet, "/api/v1/ops/tenants", token, nil)
	if rec.Code != http.StatusInternalServerError {
		t.Fatalf("数据库故障应返回 500，实际 %d", rec.Code)
	}
	body := rec.Body.String()
	for _, leak := range []string{"sql", "sqlite", "closed", "database", "SELECT"} {
		if containsFold(body, leak) {
			t.Fatalf("500 响应透出了内部细节 %q：%s", leak, body)
		}
	}
	var out map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
		t.Fatalf("解析错误响应失败: %v", err)
	}
	if out["error"] != "服务内部错误，请稍后重试" {
		t.Fatalf("500 响应体 = %v, 期望统一掩码文案", out["error"])
	}
}

// containsFold 判断字符串是否包含指定子串（忽略大小写）。
func containsFold(s, sub string) bool {
	return len(sub) == 0 || indexFold(s, sub) >= 0
}

// indexFold 返回子串在字符串中的位置（忽略大小写），找不到返回 -1。
func indexFold(s, sub string) int {
	lower := func(b byte) byte {
		if b >= 'A' && b <= 'Z' {
			return b + 32
		}
		return b
	}
	for i := 0; i+len(sub) <= len(s); i++ {
		match := true
		for j := 0; j < len(sub); j++ {
			if lower(s[i+j]) != lower(sub[j]) {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}

