func TestTmpProbeFloorUpdate(t *testing.T) {
	db := newTestDB(t)
	ctx := context.Background()

	// 1) 直接执行原始 SQL，观察行为。
	res, err := db.sql.ExecContext(ctx,
		`UPDATE tenants SET daily_quota=?
		 WHERE id=?
		   AND (SELECT COALESCE(success_count + inflight_count, 0) FROM tenant_day_usage
		        WHERE tenant_id=? AND day=?) <= ?`,
		30, "t1", "t1", "2026-01-01", 30)
	if err != nil {
		t.Logf("raw exec err=%v", err)
	} else {
		n, _ := res.RowsAffected()
		t.Logf("raw exec ok, rows=%d", n)
	}
	tenant, _ := db.GetTenant(ctx, "t1")
	t.Logf("after raw: quota=%d", tenant.DailyQuota)

	// 2) 只保留 id 条件。
	res2, err2 := db.sql.ExecContext(ctx,
		`UPDATE tenants SET daily_quota=? WHERE id=? AND (SELECT COALESCE(success_count + inflight_count, 0) FROM tenant_day_usage WHERE tenant_id=? AND day=?) <= ?`,
		31, "t1", "t1", "2026-01-01", 31)
	if err2 != nil {
		t.Logf("raw2 err=%v", err2)
	} else {
		n2, _ := res2.RowsAffected()
		t.Logf("raw2 rows=%d", n2)
	}

	// 3) 单独查子查询值。
	var v int
	err3 := db.sql.QueryRowContext(ctx,
		`SELECT COALESCE((SELECT success_count + inflight_count FROM tenant_day_usage WHERE tenant_id=? AND day=?), 0)`,
		"t1", "2026-01-01").Scan(&v)
	t.Logf("subquery value=%d err=%v", v, err3)

	// 4) 条件里直接写常量比较。
	res4, err4 := db.sql.ExecContext(ctx,
		`UPDATE tenants SET daily_quota=? WHERE id=? AND 0 <= ?`, 32, "t1", 32)
	if err4 != nil {
		t.Logf("raw4 err=%v", err4)
	} else {
		n4, _ := res4.RowsAffected()
		t.Logf("raw4 rows=%d", n4)
	}
	tenant2, _ := db.GetTenant(ctx, "t1")
	t.Logf("final quota=%d", tenant2.DailyQuota)
}

