# -*- coding: utf-8 -*-
"""探测 Gitee PR 合并阻塞点：testers 字段、仓库设置字段、可用端点。
只读探测，不做任何写操作；令牌仅从本机 MCP 配置读入内存，不打印、不落盘。
"""
import json
import re
import sys
import urllib.request
import urllib.error

MCP_JSON = r"C:\Users\26765\.minimax\mcp.json"
BASE = "https://gitee.com/api/v5"
OWNER = "xishiyao"
REPO = "d5"


def find_token(obj):
    """在 mcp.json 中递归寻找 Gitee 访问令牌（40 位十六进制或 Bearer 头）。"""
    hits = []

    def walk(o):
        if isinstance(o, dict):
            for k, v in o.items():
                if isinstance(v, str):
                    if re.fullmatch(r"[0-9a-f]{40}", v):
                        hits.append(v)
                    elif v.lower().startswith("bearer "):
                        hits.append(v[7:].strip())
                else:
                    walk(v)
        elif isinstance(o, list):
            for it in o:
                walk(it)

    walk(obj)
    # 去重并优先取非 GitHub 形态的
    seen = []
    for h in hits:
        if h not in seen:
            seen.append(h)
    return seen


def api(path, token, method="GET", body=None):
    url = BASE + path
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(url, data=data, method=method)
    req.add_header("Authorization", "token " + token)
    req.add_header("User-Agent", "d5-audit-probe")
    req.add_header("Content-Type", "application/json; charset=utf-8")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            raw = resp.read().decode("utf-8", "replace")
            return resp.status, raw
    except urllib.error.HTTPError as e:
        raw = e.read().decode("utf-8", "replace")
        return e.code, raw
    except Exception as e:  # noqa: BLE001
        return -1, repr(e)


def main():
    with open(MCP_JSON, "r", encoding="utf-8") as f:
        cfg = json.load(f)
    tokens = find_token(cfg)
    print("候选令牌数:", len(tokens))
    if not tokens:
        print("未找到令牌")
        return 2
    token = tokens[0]
    print("使用令牌指纹:", token[:4] + "…" + token[-4:], "len=", len(token))

    # 1) PR 详情
    st, raw = api(f"/repos/{OWNER}/{REPO}/pulls/1", token)
    print("\n=== GET pulls/1 ->", st)
    if st == 200:
        pr = json.loads(raw)
        keys = ["number", "state", "title", "mergeable", "merged", "html_url",
                "head", "base", "assignee", "assignees", "testers", "reviewers",
                "updated_at", "created_at", "user"]
        slim = {}
        for k in keys:
            v = pr.get(k)
            if k == "head" and isinstance(v, dict):
                v = {"label": v.get("label"), "ref": v.get("ref"), "sha": v.get("sha")}
            if k == "base" and isinstance(v, dict):
                v = {"label": v.get("label"), "ref": v.get("ref"), "sha": v.get("sha")}
            if isinstance(v, dict) and k in ("user", "assignee"):
                v = v.get("login")
            if isinstance(v, list):
                v = [{kk: (vv.get("login") if isinstance(vv, dict) else vv)
                      for kk, vv in it.items() if kk in ("id", "login", "accept", "name", "state")}
                     if isinstance(it, dict) else it for it in v]
            slim[k] = v
        print(json.dumps(slim, ensure_ascii=False, indent=2))
        allkeys = sorted(pr.keys())
        print("PR 全部字段:", allkeys)
        for k in allkeys:
            if re.search(r"test|merge|review|check|status|ci", k, re.I):
                print("  候选字段", k, "=", json.dumps(pr.get(k), ensure_ascii=False)[:400])
    else:
        print(raw[:600])

    # 2) 仓库设置
    st, raw = api(f"/repos/{OWNER}/{REPO}", token)
    print("\n=== GET repo ->", st)
    if st == 200:
        repo = json.loads(raw)
        for k in sorted(repo.keys()):
            if re.search(r"test|merge|review|check|pull|pr|protect|allow|ci", k, re.I):
                print("  ", k, "=", json.dumps(repo.get(k), ensure_ascii=False)[:300])

    # 3) 测试人列表端点
    for p in (f"/repos/{OWNER}/{REPO}/pulls/1/testers",
              f"/repos/{OWNER}/{REPO}/pulls/1/reviews",
              f"/repos/{OWNER}/{REPO}/pulls/1/merge"):
        st, raw = api(p, token)
        print("\n=== GET", p, "->", st)
        print(raw[:700])

    # 4) 拉取 Gitee OpenAPI 规范，找 tester / merge 相关端点
    for spec_url in ("https://gitee.com/api/v5/swagger.json",
                     "https://gitee.com/api/v5/swagger"):
        try:
            with urllib.request.urlopen(
                urllib.request.Request(spec_url, headers={"User-Agent": "d5-audit-probe"}),
                timeout=60) as resp:
                spec_raw = resp.read().decode("utf-8", "replace")
            print("\n=== OpenAPI", spec_url, "len=", len(spec_raw))
            try:
                spec = json.loads(spec_raw)
                paths = spec.get("paths", {})
                for pth, ops in paths.items():
                    if re.search(r"tester", pth, re.I):
                        print("  PATH", pth, "->", ",".join(ops.keys()))
                        for m, op in ops.items():
                            print("     ", m, op.get("summary"), "|", (op.get("description") or "")[:160])
                print("  含 test 的路径数:", sum(1 for p_ in paths if "test" in p_.lower()))
            except Exception as e:  # noqa: BLE001
                print("  非 JSON 规范:", repr(e)[:200])
            break
        except Exception as e:  # noqa: BLE001
            print("OpenAPI 获取失败", spec_url, repr(e)[:160])
    return 0


if __name__ == "__main__":
    sys.exit(main())

# -*- coding: utf-8 -*-
"""枚举 Gitee OpenAPI 中与 PR 测试/评审/合并相关的端点，并试探置位 testers 的可能路径。
第一阶段只读；仅在明确列出候选端点后才做最小必要写入。
"""
import json
import re
import sys
import urllib.request
import urllib.error

MCP_JSON = r"C:\Users\26765\.minimax\mcp.json"
BASE = "https://gitee.com/api/v5"
OWNER = "xishiyao"
REPO = "d5"


def find_token(obj):
    hits = []

    def walk(o):
        if isinstance(o, dict):
            for v in o.values():
                if isinstance(v, str):
                    if re.fullmatch(r"[0-9a-f]{40}", v) or v.lower().startswith("bearer "):
                        hits.append(v[7:].strip() if v.lower().startswith("bearer ") else v)
                else:
                    walk(v)
        elif isinstance(o, list):
            for it in o:
                walk(it)

    walk(obj)
    out = []
    for h in hits:
        if h not in out:
            out.append(h)
    return out


def api(path, token, method="GET", body=None):
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(BASE + path, data=data, method=method)
    req.add_header("Authorization", "token " + token)
    req.add_header("User-Agent", "d5-audit-probe")
    req.add_header("Content-Type", "application/json; charset=utf-8")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")
    except Exception as e:  # noqa: BLE001
        return -1, repr(e)


def fetch(url, timeout=60):
    req = urllib.request.Request(url, headers={"User-Agent": "d5-audit-probe"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")
    except Exception as e:  # noqa: BLE001
        return -1, repr(e)


def main():
    with open(MCP_JSON, "r", encoding="utf-8") as f:
        token = find_token(json.load(f))[0]

    # A) 抓取 swagger 页面，抽取 pulls 相关端点
    for url in ("https://gitee.com/api/v5/swagger",
                "https://gitee.com/api/v5/swagger.json",
                "https://gitee.com/api/v5/swagger.yaml",
                "https://gitee.com/api/v5/swagger/doc.json"):
        st, raw = fetch(url)
        print("\n### ", url, "->", st, "len=", len(raw))
        if st != 200:
            continue
        cands = set(re.findall(r"/repos/\{owner\}/\{repo\}/pulls[^\s\"'<>]*", raw))
        cands |= set(re.findall(r"/repos/[^\s\"'<>]*pulls[^\s\"'<>]*", raw))
        print("  pulls 相关端点:")
        for c in sorted(cands):
            print("   ", c[:160])
        for kw in ("tester", "Tester", "TEST_PASS", "test_pass"):
            idxs = [m.start() for m in re.finditer(kw, raw)][:6]
            for i in idxs:
                seg = raw[max(0, i - 160):i + 200].replace("\n", " ")
                print(f"  [{kw}] ...{seg}...")
        if cands:
            break

    # B) 试探 PR 写入类端点是否可用（先看状态码，不带副作用的优先）
    probes = [
        ("GET", f"/repos/{OWNER}/{REPO}/pulls/1/assignees", None),
        ("POST", f"/repos/{OWNER}/{REPO}/pulls/1/testers", {"testers": ["xishiyao"]}),
        ("PATCH", f"/repos/{OWNER}/{REPO}/pulls/1", {"title": "[feat] [v2.5.0] [#16221249] 企业模型服务配额管理与远端交付链路"}),
    ]
    for method, path, body in probes:
        st, raw = api(path, token, method, body)
        print(f"\n### {method} {path} -> {st}")
        print("  ", raw[:400].replace("\n", " "))
    return 0


if __name__ == "__main__":
    sys.exit(main())

