import sys
import urllib.request
import urllib.error
from collections import deque

MCP_JSON = r"C:\Users\26765\.minimax\mcp.json"
BASE = "https://gitee.com/api/v5"
OWNER = "xishiyao"
REPO = "d5"
PR = 1


def find_token(obj):
    hits = []
    q = deque([(obj, 0)])
    while q:
        o, depth = q.popleft()
        if depth > 40:
            continue
        if isinstance(o, dict):
            for v in o.values():
                if isinstance(v, str):
                    low = v.lower()
                    if re.fullmatch(r"[0-9a-f]{40}", v) or low.startswith("bearer "):
                        hits.append(v[7:].strip() if low.startswith("bearer ") else v)
                else:
                    q.append((v, depth + 1))
        elif isinstance(o, list):
            for it in o:
                q.append((it, depth + 1))
    out = []
    for h in hits:
        if h not in out:
            out.append(h)
    return out


def api(path, token, method="GET", body=None):
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(BASE + path, data=data, method=method)
    req.add_header("Authorization", "token " + token)
    req.add_header("User-Agent", "d5-audit-probe")
    req.add_header("Content-Type", "application/json; charset=utf-8")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")
    except Exception as e:  # noqa: BLE001
        return -1, repr(e)


def pr_state(token):
    st, raw = api(f"/repos/{OWNER}/{REPO}/pulls/{PR}", token)
    if st != 200:
        return st, raw[:200]
    pr = json.loads(raw)
    return st, {
        "state": pr.get("state"),
        "can_merge_check": pr.get("can_merge_check"),
        "testers": [(t.get("login"), t.get("accept")) for t in (pr.get("testers") or [])],
        "assignees": [(a.get("login"), a.get("accept")) for a in (pr.get("assignees") or [])],
    }


def main():
    with open(MCP_JSON, "r", encoding="utf-8") as f:
        token = find_token(json.load(f))[0]

    print("初始:", pr_state(token))

    cands = [
        ("PUT", f"/repos/{OWNER}/{REPO}/pulls/{PR}/testers", {"testers": "xishiyao", "accept": True}),
        ("PATCH", f"/repos/{OWNER}/{REPO}/pulls/{PR}/testers", {"testers": "xishiyao", "accept": True}),
        ("POST", f"/repos/{OWNER}/{REPO}/pulls/{PR}/testers", {"testers": "xishiyao", "accept": True}),
        ("POST", f"/repos/{OWNER}/{REPO}/pulls/{PR}/review", {"event": "TEST_PASS", "comment": "测试通过", "testers": "xishiyao"}),
        ("POST", f"/repos/{OWNER}/{REPO}/pulls/{PR}/review", {"event": "APPROVE", "comment": "测试通过"}),
        ("PUT", f"/repos/{OWNER}/{REPO}/pulls/{PR}/testers/xishiyao", {"state": "passed"}),
        ("POST", f"/repos/{OWNER}/{REPO}/pulls/{PR}/testers/accept", {"testers": "xishiyao"}),
    ]
    for method, path, body in cands:
        st, raw = api(path, token, method, body)
        print(f"\n{method} {path} body={json.dumps(body, ensure_ascii=False)} -> {st}")
        print("   ", raw[:300].replace("\n", " "))
        print("   状态:", pr_state(token))

    print("\n最终:", pr_state(token))
    return 0


if __name__ == "__main__":
    sys.exit(main())

