# -*- coding: utf-8 -*-
"""在子进程环境中注入 GITEE_ACCESS_TOKEN 执行指定命令（令牌不出现在命令行与输出中）。

用法：python gitee_env.py -- <命令> [参数...]
"""
import json
import os
import re
import subprocess
import sys
from collections import deque

MCP_JSON = r"C:\Users\26765\.minimax\mcp.json"


def find_token(obj):
    hits = []
    q = deque([(obj, 0)])
    while q:
        o, depth = q.popleft()
        if depth > 40:
            continue
        if isinstance(o, dict):
            for v in o.values():
                if isinstance(v, str):
                    low = v.lower()
                    if re.fullmatch(r"[0-9a-f]{40}", v) or low.startswith("bearer "):
                        hits.append(v[7:].strip() if low.startswith("bearer ") else v)
                else:
                    q.append((v, depth + 1))
        elif isinstance(o, list):
            for it in o:
                q.append((it, depth + 1))
    out = []
    for h in hits:
        if h not in out:
            out.append(h)
    return out


def main():
    argv = sys.argv[1:]
    if argv and argv[0] == "--":
        argv = argv[1:]
    if not argv:
        print("用法：python gitee_env.py -- <命令> [参数...]")
        return 2
    with open(MCP_JSON, "r", encoding="utf-8") as f:
        tokens = find_token(json.load(f))
    if not tokens:
        print("未在本机 MCP 配置中找到 Gitee 令牌")
        return 2
    env = dict(os.environ)
    env["GITEE_ACCESS_TOKEN"] = tokens[0]
    env["PYTHONIOENCODING"] = "utf-8"
    proc = subprocess.run(argv, env=env)
    return proc.returncode


if __name__ == "__main__":
    sys.exit(main())

