# -*- coding: utf-8 -*-
"""尝试用令牌直接调用 Gitee 界面的「测试通过」端点（PR !2），以减少人工点击。

依次尝试常见的令牌传参方式；全部失败则如实返回，交由账号本人在界面点击。
"""
import json
import os
import sys
import urllib.error
import urllib.request

PR = int(sys.argv[1]) if len(sys.argv) > 1 else 2
OWNER, NAME = "xishiyao", "d5"
token = os.environ["GITEE_ACCESS_TOKEN"]
base = f"https://gitee.com/{OWNER}/{NAME}/pulls/{PR}"


def try_url(url: str, label: str) -> dict:
    req = urllib.request.Request(url, headers={
        "Authorization": f"token {token}",
        "User-Agent": "Mozilla/5.0 d5-probe",
        "Accept": "application/json, text/html",
    })
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            raw = resp.read().decode("utf-8", "replace")
            return {"label": label, "status": resp.status, "url": url.split("?")[0],
                    "body": raw[:200], "final_url": resp.geturl()[:160]}
    except urllib.error.HTTPError as e:
        return {"label": label, "status": e.code, "url": url.split("?")[0],
                "body": e.read().decode("utf-8", "replace")[:200]}
    except Exception as e:  # noqa: BLE001
        return {"label": label, "status": -1, "url": url.split("?")[0], "body": repr(e)[:200]}


def pr_state() -> dict:
    req = urllib.request.Request(f"https://gitee.com/api/v5/repos/{OWNER}/{NAME}/pulls/{PR}",
                                 headers={"Authorization": f"token {token}", "User-Agent": "d5-probe"})
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            pr = json.loads(resp.read().decode("utf-8"))
        return {"state": pr.get("state"),
                "testers": [(t.get("login"), t.get("accept")) for t in pr.get("testers") or []],
                "assignees": [(a.get("login"), a.get("accept")) for a in pr.get("assignees") or []],
                "can_merge_check": pr.get("can_merge_check")}
    except Exception as e:  # noqa: BLE001
        return {"error": repr(e)[:200]}


print("调用前 PR 状态:", json.dumps(pr_state(), ensure_ascii=False))

attempts = [
    (f"{base}/accept_test?access_token={token}", "web accept_test + access_token"),
    (f"{base}/accept_test?private_token={token}", "web accept_test + private_token"),
    (f"{base}/accept_test", "web accept_test + Authorization 头"),
    (f"https://gitee.com/api/v5/repos/{OWNER}/{NAME}/pulls/{PR}/accept_test", "api v5 accept_test"),
]
for url, label in attempts:
    res = try_url(url, label)
    print(f"  [{res['status']}] {label} -> {res['body'][:120]!r}")
    st = pr_state()
    if st.get("testers") and any(t[1] for t in st["testers"]):
        print("  => testers.accept 已置位", json.dumps(st, ensure_ascii=False))
        break
else:
    print("调用后 PR 状态:", json.dumps(pr_state(), ensure_ascii=False))
    print("未置位：需账号本人在界面点击「测试通过」。")

