package httpapi

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// 本文件补齐**异常入参分支**的用例：
// GitHub Actions 的 CI 门禁在 Linux + go1.27.4 下按同一套覆盖率口径复算，
// httpapi 包曾因此低于 85%（84.2%，差 5 条语句）。这里补的是真实缺失的分支覆盖：
// 方法不符、请求体不是合法 JSON、运营账号缺少租户范围——都是题面 R1/R7 明确要求的行为，
// 之前只测了成功路径。

// doRaw 发起一次原始请求体请求（用于构造非法 JSON 等异常入参）。
func doRaw(t *testing.T, h http.Handler, method, path, token, body string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

// appToken 用凭证密钥登录，返回客户应用令牌。
func appToken(t *testing.T, h http.Handler, secret string) string {
	t.Helper()
	rec := do(t, h, http.MethodPost, "/api/v1/auth/login", "", map[string]string{"secret": secret})
	if rec.Code != http.StatusOK {
		t.Fatalf("凭证登录状态码 = %d: %s", rec.Code, rec.Body.String())
	}
	var out struct {
		Token string `json:"token"`
	}
	decodeJSONBody(t, rec, &out)
	return out.Token
}

// TestWriteEndpointsRejectWrongMethod 只允许 POST 的接口在方法不符时必须返回 405，
// 而不是落到业务逻辑里（R1/R6 的写操作入口约束）。
func TestWriteEndpointsRejectWrongMethod(t *testing.T) {
	srv, _ := newTestServer(t)
	h := srv.Handler()
	adminToken := login(t, h, "admin-a", "admin-a-****")
	clientToken := appToken(t, h, "sk-a1")

	cases := []struct {
		name  string
		path  string
		token string
	}{
		{"创建凭证", "/api/v1/admin/credentials/create", adminToken},
		{"停用凭证", "/api/v1/admin/credentials/disable", adminToken},
		{"发起调用", "/api/v1/app/invoke", clientToken},
	}
	for _, c := range cases {
		rec := do(t, h, http.MethodGet, c.path, c.token, nil)
		if rec.Code != http.StatusMethodNotAllowed {
			t.Fatalf("%s：方法不符应返回 405，实际 %d: %s", c.name, rec.Code, rec.Body.String())
		}
	}
}

// TestWriteEndpointsRejectInvalidJSON 请求体不是合法 JSON 时必须返回 400，
// 不能把解析失败当成业务入参继续执行。
func TestWriteEndpointsRejectInvalidJSON(t *testing.T) {
	srv, _ := newTestServer(t)
	h := srv.Handler()
	adminToken := login(t, h, "admin-a", "admin-a-****")
	clientToken := appToken(t, h, "sk-a1")

	rec := doRaw(t, h, http.MethodPost, "/api/v1/admin/credentials/create", adminToken, "{不是 JSON")
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("创建凭证：非法 JSON 应返回 400，实际 %d: %s", rec.Code, rec.Body.String())
	}
	rec = doRaw(t, h, http.MethodPost, "/api/v1/app/invoke", clientToken, "{不是 JSON")
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("发起调用：非法 JSON 应返回 400，实际 %d: %s", rec.Code, rec.Body.String())
	}
}

// TestOpsScopeRequiresTenantID 运营账号跨租户操作必须显式给出 tenant_id（R1/R7），
// 缺少租户范围时返回 400。
func TestOpsScopeRequiresTenantID(t *testing.T) {
	srv, _ := newTestServer(t)
	h := srv.Handler()
	opsToken := login(t, h, "ops", "ops-****")

	rec := do(t, h, http.MethodGet, "/api/v1/admin/credentials", opsToken, nil)
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("运营缺少 tenant_id 应返回 400，实际 %d: %s", rec.Code, rec.Body.String())
	}
	rec = do(t, h, http.MethodGet, "/api/v1/admin/requests", opsToken, nil)
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("运营缺少 tenant_id 应返回 400，实际 %d: %s", rec.Code, rec.Body.String())
	}
}

package upstream

import (
	"context"
	"errors"
	"io"
	"net/http"
	"strings"
	"testing"
	"time"
)

// 本文件补齐 HTTP 上游客户端的**异常分支**覆盖：
// GitHub Actions 的 CI 门禁在 Linux + go1.27.4 下复算覆盖率时，
// upstream 包为 83.8%（差 1 条语句）。补的是真实缺失的分支：
// 迟到等待窗口未配置、上游地址非法、调用方已取消、响应体读取失败、迟到窗口内才拿到结果。

// errBody 是一个读取即失败的响应体，用来触发「读取上游响应失败」分支。
type errBody struct{}

func (errBody) Read([]byte) (int, error) { return 0, errors.New("读取中断") }
func (errBody) Close() error               { return nil }

// roundTripFunc 把函数适配成 http.RoundTripper。
type roundTripFunc func(*http.Request) (*http.Response, error)

func (f roundTripFunc) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

// TestCompleteUsesDefaultLateWait 未显式配置迟到等待窗口时回落到默认值，
// 不能让后台协程没有上限地等待。
func TestCompleteUsesDefaultLateWait(t *testing.T) {
	srv := newLocalServer(t, func(w http.ResponseWriter, r *http.Request) {
		writeJSONResponse(w, "up-1", "模型输出")
	})
	defer srv.Close()

	c := NewHTTPCallier(srv.URL, srv.Client(), "test")
	c.LateWait = 0 // 触发回落到 DefaultLateWait
	resp, err := c.Complete(context.Background(), Request{Model: "m", Prompt: "p"}, time.Second)
	if err != nil {
		t.Fatalf("调用上游失败: %v", err)
	}
	if resp.UpstreamID != "up-1" {
		t.Fatalf("上游标识 = %s", resp.UpstreamID)
	}
}

// TestCompleteInvalidBaseURL 上游地址非法时必须返回可读的错误，
// 而不是 panic 或空结果。
func TestCompleteInvalidBaseURL(t *testing.T) {
	c := NewHTTPCallier("http://非法 主机地址", &http.Client{}, "test")
	_, err := c.Complete(context.Background(), Request{Model: "m", Prompt: "p"}, time.Second)
	if err == nil {
		t.Fatalf("非法上游地址应返回错误")
	}
	if !strings.Contains(err.Error(), "构造上游请求失败") {
		t.Fatalf("错误信息 = %v，期望包含「构造上游请求失败」", err)
	}
}

// TestCompleteCallerCancelled 调用方在超时前取消时，超时判定分支直接结束，
// 不再等待迟到结果。
func TestCompleteCallerCancelled(t *testing.T) {
	srv := newLocalServer(t, func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(300 * time.Millisecond)
		writeJSONResponse(w, "up-1", "模型输出")
	})
	defer srv.Close()

	ctx, cancel := context.WithCancel(context.Background())
	c := NewHTTPCallier(srv.URL, srv.Client(), "test")
	go func() {
		time.Sleep(30 * time.Millisecond)
		cancel()
	}()
	_, err := c.Complete(ctx, Request{Model: "m", Prompt: "p"}, 80*time.Millisecond)
	if !errors.Is(err, ErrTimeout) {
		t.Fatalf("期望 ErrTimeout，实际 %v", err)
	}
}

// TestCompleteBodyReadFailure 上游响应体读取失败时返回明确错误。
func TestCompleteBodyReadFailure(t *testing.T) {
	client := &http.Client{Transport: roundTripFunc(func(r *http.Request) (*http.Response, error) {
		return &http.Response{
			StatusCode: http.StatusOK,
			Body:       errBody{},
			Header:     http.Header{"Content-Type": []string{"application/json"}},
		}, nil
	})}
	c := NewHTTPCallier("http://upstream.invalid", client, "test")
	_, err := c.Complete(context.Background(), Request{Model: "m", Prompt: "p"}, time.Second)
	if err == nil {
		t.Fatalf("读取失败应返回错误")
	}
	if !strings.Contains(err.Error(), "读取上游响应失败") {
		t.Fatalf("错误信息 = %v，期望包含「读取上游响应失败」", err)
	}
}

// TestCompleteLateWindowClosed 结果在迟到等待窗口关闭之后才到达时，
// 按超时处理（R4：迟到结果只留诊断，不改终态）。
func TestCompleteLateWindowClosed(t *testing.T) {
	client := &http.Client{Transport: roundTripFunc(func(r *http.Request) (*http.Response, error) {
		body := &delayedBody{delay: 120 * time.Millisecond, data: `{"upstream_id":"up-1","content":"迟到输出"}`}
		return &http.Response{
			StatusCode: http.StatusOK,
			Body:       body,
			Header:     http.Header{"Content-Type": []string{"application/json"}},
		}, nil
	})}
