// delayedBody 在读取时延迟返回内容。
type delayedBody struct {
	delay time.Duration
	data  string
	off   int
}

func (b *delayedBody) Read(p []byte) (int, error) {
	if b.off == 0 {
		time.Sleep(b.delay)
	}
	if b.off >= len(b.data) {
		return 0, io.EOF
	}
	n := copy(p, b.data[b.off:])
	b.off += n
	return n, nil
}

func (b *delayedBody) Close() error { return nil }

