# -*- coding: utf-8 -*-
"""从会话事件清单抽取关键产物的首次写入时刻（v3 阶段顺序证据）。"""
import io
import json

TARGETS = [
    "docs/01-需求分析.md", "docs/02-原型设计.md", "docs/03-任务规划.md", "docs/05-假设清单.md",
    "AGENTS.md", "docs/agents/AGENTS-v1.0.md", "skills/quota-guard/SKILL.md",
    "skills/acceptance-audit/SKILL.md", ".github/workflows/ci.yml", "internal/domain/domain.go",
    "internal/service/service.go", "internal/httpapi/server.go", "docs/06-会话导出.md",
    "docs/08-Skill使用记录.md", "docs/09-AI使用说明.md", "docs/10-交付与发布说明.md",
    "docs/12-讲解视频带时间点目录.md", "docs/13-讲解视频录制检查单.md", "docs/11-班级群提交消息.md",
    "evidence/independent-test-report.md", "evidence/independent-acceptance-report.md",
]
WRITE_TOOLS = ("write", "edit", "str_replace_editor", "create_file")

first = {}
prompts = []
for line in io.open("evidence/会话事件清单.jsonl", encoding="utf-8"):
    try:
        d = json.loads(line)
    except Exception:
        continue
    if d.get("kind") == "tool_call":
        tool = str(d.get("tool", ""))
        args = d.get("arguments") or {}
        path = str(args.get("path") or args.get("file_path") or args.get("file") or "")
        if tool in WRITE_TOOLS or "write" in tool or "edit" in tool:
            norm = path.replace("\\", "/")
            for t in TARGETS:
                if t in norm and t not in first:
                    first[t] = d.get("time", "")
    elif d.get("kind") == "prompt" and d.get("origin") == "user":
        prompts.append((d.get("time", ""), (d.get("summary") or "")[:70]))

print("=== 首次写入时刻 ===")
for t in sorted(TARGETS, key=lambda x: first.get(x, "zzz")):
    print(first.get(t, "?"), "|", t)
print("=== 用户提示条数：%d，前 6 条 ===" % len(prompts))
for t, s in prompts[:6]:
    print(t, "|", s)

