violations=[]
for trial in range(25):
    # 1) 把额度抬高到 50，制造很宽的陈旧读取窗口
    s,_=req("POST","/api/v1/ops/tenants/quota",{"tenant_id":"tenant-b","daily_quota":50,"reason":f"抬到50 {trial}"},ops)
